-- Parameterized cash-register report queries for the ADN MySQL/MariaDB schema.
-- Extracted from agent/master-machine/queries/cash_report_*.sql (FastReport exports).
-- Each section binds params in this exact order (see main.go):
--   Datos, ResumenT1, ResumenT2: date, date, caja, caja, date, date, caja, caja
--   Ventas: caja, caja, date, date
--   Billetes: caja

-- name: Datos
SELECT MBC_ID AS ID, ROUND(IF(MBC_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MBC_MONTO/PERSONALIZAR_GET_TASA("USD", MBC_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MBC_MONTO / IF(MBC_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MBC_DESCRIPCION) > 10 OR MBC_DESCRIPCION = "" OR MBC_DESCRIPCION = "0000-00-00",MBC_FECHA,MBC_DESCRIPCION)), MBC_VALORCAM2),MBC_MONTO)), MBC_MONTOOTRAMONEDA),2) AS MONTOOTRAMONEDA, MBC_MONTO AS MONTO, IF(MBC_MONTO < 0 AND MBC_OBC_TIPO = "TRANR" AND LEFT(MBC_REC_NUMERO,1) = "D","VUELTOS PENDIENTES PAGADOS",IF(BCO_NOMBRE = "VUELTOS PENDIENTES", CONCAT("CRUCE ",BCO_NOMBRE),BCO_NOMBRE)) AS MEDIO, IF( MBC_MONTO < 0 AND MBC_OBC_TIPO = "TRANR" AND LEFT(MBC_REC_NUMERO, 1) = "D", CONCAT(BCO_NOMBRE," "), IF(BCO_NOMBRE = "VUELTOS PENDIENTES", CONCAT("CRUCE ",BCO_NOMBRE),BCO_NOMBRE)) AS BANCO, IFNULL( IF(MBC_CLT_CODIGO <> "", MBC_CLT_CODIGO, IF(MBC_REC_NUMERO <> "", (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MBC_REC_NUMERO)), (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MBC_NUMERO) ))), IFNULL( (SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MBC_NUMERO AND DCL_TIPTRA="D" AND DCL_TDT_CODIGO="FAV" AND DCL_FECHA=MBC_FECHA), (SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MBC_NUMERO AND DCL_TIPTRA="D" AND DCL_TDT_CODIGO="DEV"))) AS CLT_CODIGO, (SELECT CC.CLT_NOMBRE FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO= IFNULL( IF(MBC_CLT_CODIGO <> "", MBC_CLT_CODIGO, IF(MBC_REC_NUMERO <> "", (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MBC_REC_NUMERO)), (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MBC_NUMERO) ))), IFNULL((SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MBC_NUMERO AND DB.DCL_TIPTRA="D" AND DB.DCL_TDT_CODIGO="FAV" AND DB.DCL_FECHA=MBC_FECHA),(SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MBC_NUMERO AND DB.DCL_TIPTRA="D" AND DB.DCL_TDT_CODIGO="DEV"))) ) AS cltNombre, DATE_FORMAT(MBC_FECHA,"%Y-%m-%d") AS FECHA, TRUNCATE(IF(MBC_VALORCAM = "0", IFNULL(IF(MBC_DESCRIPCION="INGRESO DE FACTURA DE VENTA",(SELECT MAX(DCL_VALORCAM) FROM ADN_DOCCLI WHERE DCL_NUMERO = ADN_MOVBCO.MBC_NUMERO AND DCL_TDT_CODIGO IN ("FAV","NEN") AND DCL_TIPTRA = "D" AND DCL_ACTIVO = "1" AND DCL_FECHA = MBC_FECHA AND DCL_HORA BETWEEN DATE_ADD(MBC_HORA, INTERVAL -20 SECOND) AND DATE_ADD(MBC_HORA, INTERVAL 20 SECOND)), (SELECT B.DCL_VALORCAM FROM ADN_DOCCLI B WHERE B.DCL_TDT_CODIGO IN ("FAV","NEN") AND B.DCL_TIPTRA="D" AND B.DCL_CLT_CODIGO=ADN_MOVBCO.MBC_CLT_CODIGO AND B.DCL_FECHA=ADN_MOVBCO.MBC_FECHA AND B.DCL_HORA BETWEEN DATE_ADD(MBC_HORA, INTERVAL -20 SECOND) AND DATE_ADD(MBC_HORA, INTERVAL 20 SECOND))), IFNULL((SELECT B.DCL_VALORCAM FROM ADN_DOCCLI B WHERE B.DCL_REC_NUMERO=MBC_REC_NUMERO AND DCL_TIPTRA="P" LIMIT 1 OFFSET 0),PERSONALIZAR_GET_TASA("USD",MBC_FECHA))), MBC_VALORCAM),2) AS tsaUSD, IF(MBC_VALORCAM = "0", PERSONALIZAR_GET_TASA("COP",MBC_FECHA),MBC_VALORCAM) AS tsaCOP, IF((BCO_NOMBRE LIKE "%EFECTIVO%" OR MBC_TTB_CODIGO IN ("INGV")),"No aplica",MBC_NUMERO) AS REF, IF(MBC_TTB_CODIGO NOT IN ("EGRV","INGV") AND MBC_MONTO > 0, "INGRESO DE FACTURA DE VENTA", MBC_DESCRIPCION) AS MBC_DESCRIPCION, IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") AS TIPOTRANS, IFNULL(IF(MBC_DESCRIPCION="INGRESO DE FACTURA DE VENTA",CONCAT(IF(MBC_MODFIS="","NEN","FAV"),"-",(SELECT RIGHT(B.DCL_NUMERO,8) FROM ADN_DOCCLI B WHERE B.DCL_REC_NUMERO=IF(MBC_NUMERO<>"",MBC_NUMERO,MBC_REC_NUMERO) AND DCL_TIPTRA="P" LIMIT 1 OFFSET 0)), (SELECT CONCAT(B.DCL_TDT_CODIGO,"-",RIGHT(B.DCL_NUMERO,8)) FROM ADN_DOCCLI B WHERE B.DCL_REC_NUMERO=IF(MBC_DOCORIGEN<>"",MBC_DOCORIGEN,MBC_REC_NUMERO) AND DCL_TIPTRA="P" LIMIT 1 OFFSET 0)),"") AS DOC, UPPER(SUBSTRING_INDEX(USER(), "@", "1")) AS USUARIO_IMP, UPPER(IF(SUBSTRING_INDEX(USER(), "@", "-1")="localhost","SERVIDOR", SUBSTRING_INDEX(USER(), "@", "-1")))AS ESTACION, "//ServidorADN//fotos//Logo.png" AS LOGO FROM adn_movbco INNER JOIN ADN_BANCOS ON BCO_CODIGO=MBC_CBC_BCO_CODIGO WHERE BCO_CODIGO NOT IN ("023","025") AND MBC_FECHA >= ? AND MBC_FECHA <= ? AND TIME(MBC_FECHAHORA)>="07:00:00" AND TIME(MBC_FECHAHORA)<="20:00:00" AND MBC_ACTIVO = "1" AND IF(?="",1,MBC_IDCAJA=?) HAVING CLT_CODIGO IS NOT NULL UNION ALL SELECT MCJ_ID, ROUND(IF(MCJ_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MCJ_MONTO/PERSONALIZAR_GET_TASA("USD", MCJ_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MCJ_MONTO/ IF(MCJ_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MCJ_DESCRIPCION) > 10 OR MCJ_DESCRIPCION = "" OR MCJ_DESCRIPCION = "0000-00-00",MCJ_FECHA,MCJ_DESCRIPCION)), MCJ_VALORCAM2),MCJ_MONTO)), MCJ_MONTOOTRAMONEDA),2) AS MONTOOTRAMONEDA, MCJ_MONTO AS MONTO, IF(MCJ_INS_CODIGO="EFE","EFECTIVO",IF(MCJ_INS_CODIGO="TDB","PUNTO DE VENTA",BCO_NOMBRE)) AS MEDIO, IF(MCJ_INS_CODIGO="EFE","EFECTIVO",BCO_NOMBRE) AS BANCO, IFNULL( IF(MCJ_CLT_CODIGO <> "", MCJ_CLT_CODIGO, IF(MCJ_REC_NUMERO <> "", (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MCJ_REC_NUMERO)), (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MCJ_NUMERO) ))), (SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MCJ_NUMERO AND DCL_TIPTRA="D" AND DCL_TDT_CODIGO="FAV")) AS CLT_CODIGO, (SELECT CC.CLT_NOMBRE FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO= IFNULL( IF(MCJ_CLT_CODIGO <> "", MCJ_CLT_CODIGO, IF(MCJ_REC_NUMERO <> "", (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MCJ_REC_NUMERO)), (SELECT CC.CLT_CODIGO FROM ADN_CLIENTES CC WHERE CC.CLT_CODIGO = (SELECT R.REC_CLT_CODIGO FROM ADN_RECIBOS R WHERE R.REC_NUMERO=MCJ_NUMERO) ))), (SELECT DB.DCL_CLT_CODIGO FROM ADN_DOCCLI DB WHERE DB.DCL_NUMERO=MCJ_NUMERO AND DCL_TIPTRA="D" AND DCL_TDT_CODIGO="FAV")) ) AS cltNombre, DATE_FORMAT(MCJ_FECHA,"%Y-%m-%d") AS FECHA, IF(MCJ_VALORCAM = "0", PERSONALIZAR_GET_TASA("USD",MCJ_FECHA),MCJ_VALORCAM) AS tsaUSD, IF(MCJ_VALORCAM = "0", PERSONALIZAR_GET_TASA("COP",MCJ_FECHA),MCJ_VALORCAM) AS tsaCOP, MCJ_NUMCONFIR AS NUMERO, "INGRESO DE FACTURA DE VENTA" MCJ_DESCRIPCION, IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"PUNTO DE VENTA") AS TIPOTRANS, (SELECT CONCAT(B.DCL_TDT_CODIGO,"-",RIGHT(B.DCL_NUMERO,8)) FROM ADN_DOCCLI B WHERE B.DCL_TDT_CODIGO IN ("FAV","NEN","NENCR","DEV") AND B.DCL_TIPTRA="P" AND B.DCL_REC_NUMERO=ADN_MOVCAJA.MCJ_REC_NUMERO LIMIT 1 OFFSET 0) AS DOC, UPPER(SUBSTRING_INDEX(USER(), "@", "1")) AS USUARIO_IMP, UPPER(IF(SUBSTRING_INDEX(USER(), "@", "-1")="localhost","SERVIDOR", SUBSTRING_INDEX(USER(), "@", "-1")))AS ESTACION, "//ServidorADN//fotos//Logo.png" AS LOGO FROM adn_movcaja LEFT JOIN ADN_BANCOS ON BCO_CODIGO = MCJ_MFI_CODIGO WHERE MCJ_FECHA >= ? AND MCJ_FECHA <= ? AND TIME(MCJ_FECHAHORA)>="07:00:00" AND TIME(MCJ_FECHAHORA)<="20:00:00" AND MCJ_ACTIVO = "1" AND IF(?="",1,MCJ_IDCAJA=?) HAVING CLT_CODIGO IS NOT NULL ORDER BY TIPOTRANS,BANCO, 14, 3 DESC;

-- name: ResumenT1
SELECT COUNT(*) AS cantidad, ROUND(SUM(IF(MBC_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MBC_MONTO/PERSONALIZAR_GET_TASA("USD", MBC_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MBC_MONTO/ IF(MBC_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MBC_DESCRIPCION) > 10 OR MBC_DESCRIPCION = "" OR MBC_DESCRIPCION = "0000-00-00",MBC_FECHA,MBC_DESCRIPCION)), MBC_VALORCAM2),MBC_MONTO)), MBC_MONTOOTRAMONEDA)),2) AS MONTOOTRAMONEDA, CAST(SUM(MBC_MONTO) AS DOUBLE) AS MONTO, IF(BCO_NOMBRE = "VUELTOS PENDIENTES", CONCAT("CRUCE ",BCO_NOMBRE),BCO_NOMBRE) AS NOMBRE, IF(BCO_NOMBRE LIKE "%EFECTIVO%","EFECTIVO", "TRANSACCIONES DIGITALES") AS TIPOTRANS FROM ADN_MOVBCO INNER JOIN ADN_BANCOS ON BCO_CODIGO = MBC_CBC_BCO_CODIGO LEFT JOIN ADN_RECIBOS ON REC_NUMERO = MBC_REC_NUMERO WHERE MBC_ACTIVO = "1" AND BCO_CODIGO NOT IN ("023","025") AND MBC_FECHA >= ? AND MBC_FECHA <= ? AND TIME(MBC_FECHAHORA)>="07:00:00" AND TIME(MBC_FECHAHORA)<="20:00:00" AND IF(?="",1,MBC_IDCAJA=?) GROUP BY NOMBRE HAVING TIPOTRANS = "EFECTIVO" UNION ALL SELECT COUNT(*) AS CANT, ROUND(SUM(IF(MCJ_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MCJ_MONTO/PERSONALIZAR_GET_TASA("USD", MCJ_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MCJ_MONTO/ IF(MCJ_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MCJ_DESCRIPCION) > 10 OR MCJ_DESCRIPCION = "" OR MCJ_DESCRIPCION = "0000-00-00",MCJ_FECHA,MCJ_DESCRIPCION)), MCJ_VALORCAM2),MCJ_MONTO)), MCJ_MONTOOTRAMONEDA)),2) AS MONTOOTRAMONEDA, CAST(SUM(MCJ_MONTO) AS DOUBLE) AS MONTO, IF(MCJ_INS_CODIGO="TDB","PUNTO DE VENTA", "EFECTIVO BOLIVARES") AS NOMBRE, IF(MCJ_INS_CODIGO="TDB","TRANSACCIONES DIGITALES", "EFECTIVO") AS TIPOTRANS FROM ADN_MOVCAJA INNER JOIN ADN_CAJA ON CAJ_CODIGO = MCJ_CAJ_CODIGO LEFT JOIN ADN_BANCOS ON BCO_CODIGO = MCJ_BCO_CODIGO LEFT JOIN ADN_RECIBOS ON REC_NUMERO = MCJ_REC_NUMERO WHERE MCJ_ACTIVO = "1" AND MCJ_FECHA >= ? AND MCJ_FECHA <= ? AND IF(?="",1,MCJ_IDCAJA=?) AND TIME(MCJ_FECHAHORA)>="07:00:00" AND TIME(MCJ_FECHAHORA)<="20:00:00" GROUP BY NOMBRE HAVING TIPOTRANS = "EFECTIVO" ORDER BY TIPOTRANS, NOMBRE;

-- name: ResumenT2
SELECT COUNT(*) AS cantidad, ROUND(SUM(IF(MBC_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MBC_MONTO/PERSONALIZAR_GET_TASA("USD", MBC_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MBC_MONTO/ IF(MBC_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MBC_DESCRIPCION) > 10 OR MBC_DESCRIPCION = "" OR MBC_DESCRIPCION = "0000-00-00",MBC_FECHA,MBC_DESCRIPCION)), MBC_VALORCAM2),MBC_MONTO)), MBC_MONTOOTRAMONEDA)),2) AS MONTOOTRAMONEDA, SUM(MBC_MONTO) AS MONTO, IF(BCO_NOMBRE = "VUELTOS PENDIENTES", CONCAT("CRUCE ",BCO_NOMBRE),BCO_NOMBRE) AS NOMBRE, IF(BCO_NOMBRE LIKE "%EFECTIVO%","EFECTIVO", "TRANSACCIONES DIGITALES") AS TIPOTRANS FROM ADN_MOVBCO INNER JOIN ADN_BANCOS ON BCO_CODIGO = MBC_CBC_BCO_CODIGO LEFT JOIN ADN_RECIBOS ON REC_NUMERO = MBC_REC_NUMERO WHERE MBC_ACTIVO = "1" AND BCO_CODIGO NOT IN ("023","025") AND MBC_FECHA >= ? AND MBC_FECHA <= ? AND TIME(MBC_FECHAHORA)>="07:00:00" AND TIME(MBC_FECHAHORA)<="20:00:00" AND IF(?="",1,MBC_IDCAJA=?) GROUP BY NOMBRE HAVING TIPOTRANS = "TRANSACCIONES DIGITALES" UNION ALL SELECT COUNT(*) AS CANT, ROUND(SUM(IF(MCJ_MONTOOTRAMONEDA=0, IF(IF(BCO_NOMBRE IN("BANCO DOLARES","BANCO EFECTIVO PESOS"),BCO_NOMBRE,"TRANSFERENCIAS") = "TRANSFERENCIAS", MCJ_MONTO/PERSONALIZAR_GET_TASA("USD", MCJ_FECHA), IF(BCO_NOMBRE = "BANCO EFECTIVO PESOS",MCJ_MONTO/ IF(MCJ_VALORCAM2 = "0", PERSONALIZAR_GET_TASA("COP",IF(LENGTH(MCJ_DESCRIPCION) > 10 OR MCJ_DESCRIPCION = "" OR MCJ_DESCRIPCION = "0000-00-00",MCJ_FECHA,MCJ_DESCRIPCION)), MCJ_VALORCAM2),MCJ_MONTO)), MCJ_MONTOOTRAMONEDA)),2) AS MONTOOTRAMONEDA, SUM(MCJ_MONTO) AS MONTO, IF(MCJ_INS_CODIGO="TDB","PUNTO DE VENTA", "EFECTIVO BOLIVARES") AS NOMBRE, IF(MCJ_INS_CODIGO="TDB","TRANSACCIONES DIGITALES", "EFECTIVO") AS TIPOTRANS FROM ADN_MOVCAJA INNER JOIN ADN_CAJA ON CAJ_CODIGO = MCJ_CAJ_CODIGO LEFT JOIN ADN_BANCOS ON BCO_CODIGO = MCJ_BCO_CODIGO LEFT JOIN ADN_RECIBOS ON REC_NUMERO = MCJ_REC_NUMERO WHERE MCJ_ACTIVO = "1" AND MCJ_FECHA >= ? AND MCJ_FECHA <= ? AND TIME(MCJ_FECHAHORA)>="07:00:00" AND TIME(MCJ_FECHAHORA)<="20:00:00" AND IF(?="",1,MCJ_IDCAJA=?) GROUP BY NOMBRE HAVING TIPOTRANS = "TRANSACCIONES DIGITALES" ORDER BY TIPOTRANS, NOMBRE;

-- name: Ventas
SELECT DCL_ID, DCL_TDT_CODIGO, DCL_NUMERO, DCL_BASEG, DCL_EXENTO, DCL_NETO, ROUND(DCL_NETO / DCL_VALORCAM,2 ) AS NETOUSD, DCL_VALORCAM, DCL_IDCAJA, IF(DCL_TDT_CODIGO="FAV", DCL_NETO, 0 ) AS NETOFAV, IF(DCL_TDT_CODIGO="FAV", ROUND(DCL_NETO / DCL_VALORCAM,2) , 0 ) AS NETOFAVUSD, IF(DCL_TDT_CODIGO="NEN", DCL_NETO, 0 ) AS NETONEN, IF(DCL_TDT_CODIGO="NEN", ROUND(DCL_NETO / DCL_VALORCAM,2) , 0 ) AS NETONENUSD, IF(DCL_TDT_CODIGO="DEV", DCL_NETO, 0 ) AS NETODEV, IF(DCL_TDT_CODIGO="DEV", ROUND(DCL_NETO / DCL_VALORCAM,2) , 0 ) AS NETODEVUSD, IF(DCL_TDT_CODIGO="FAV", DCL_BASEG, 0 ) AS BASEFAV, IF(DCL_TDT_CODIGO="FAV", ROUND(DCL_BASEG / DCL_VALORCAM,2) , 0 ) AS BASEFAVUSD, IF(DCL_TDT_CODIGO="NEN", DCL_BASEG, 0 ) AS BASENEN, IF(DCL_TDT_CODIGO="NEN", ROUND(DCL_BASEG / DCL_VALORCAM,2) , 0 ) AS BASENENUSD, IF(DCL_TDT_CODIGO="FAV", DCL_EXENTO, 0 ) AS EXENTOFAV, IF(DCL_TDT_CODIGO="FAV", ROUND(DCL_EXENTO / DCL_VALORCAM,2) , 0 ) AS EXENTOFAVUSD, IF(DCL_TDT_CODIGO="NEN", DCL_EXENTO, 0 ) AS EXENTONEN, IF(DCL_TDT_CODIGO="NEN", ROUND(DCL_EXENTO / DCL_VALORCAM,2) , 0 ) AS EXENTONENUSD FROM adn_doccli WHERE DCL_TDT_CODIGO IN("FAV","FAM","NEN","DEV") AND DCL_TIPTRA="D" AND DCL_ACTIVO="1" AND IF(?="" , 1 ,DCL_IDCAJA=?) AND DCL_FECHA>=? AND DCL_FECHA<=? AND TIME(DCL_HORA)>="07:00:00" AND TIME(DCL_HORA)<="20:00:00";

-- name: Billetes
SELECT * FROM ADN_BILLETES WHERE BLT_USER IN (SELECT dcl_usuario FROM adn_doccli WHERE dcl_idcaja = ? AND TIME(dcl_FECHAHORA)>="07:00:00" AND TIME(dcl_FECHAHORA)<="20:00:00");
